const BASE_URL = "{{BASE_URL}}";
const API_KEY = "{{API_KEY}}";
const artifactId = "art_9b1e4d7c2a6f48e3b5c0d1a2e3f4b5c6";

const resp = await fetch(`${BASE_URL}/v1/artifacts/${artifactId}`, {
  headers: { Authorization: `Bearer ${API_KEY}` },
});
if (!resp.ok) throw new Error(JSON.stringify(await resp.json()));
const blob = await resp.blob();
console.log(resp.headers.get("Content-Type"), blob.size);
// 浏览器中可用 URL.createObjectURL(blob) 预览或触发下载
